package week_01;
import javax.swing.*;import java.awt.*;
public class frm_TongHop extends JFrame {
 private final JComboBox<String> algo=new JComboBox<>(CipherTongHop.names());private final JTextArea plain=new JTextArea(4,52),cipher=new JTextArea(4,52);private final JTextField key=new JTextField(24);private final JLabel status=new JLabel("Sẵn sàng. Lịch sử lưu trong SQLite.");
 public frm_TongHop(){super("Chương trình tổng hợp - 6 thuật toán");setDefaultCloseOperation(DISPOSE_ON_CLOSE);setSize(800,620);setLocationRelativeTo(null);setLayout(new BorderLayout(10,10));JPanel p=new JPanel(new GridBagLayout());p.setBorder(BorderFactory.createEmptyBorder(16,22,8,22));GridBagConstraints g=new GridBagConstraints();g.insets=new Insets(5,5,5,5);g.fill=GridBagConstraints.HORIZONTAL;g.gridx=0;g.gridy=0;g.gridwidth=2;JLabel t=new JLabel("CHƯƠNG TRÌNH TỔNG HỢP 6 THUẬT TOÁN CỔ ĐIỂN");t.setFont(new Font("Segoe UI",1,18));p.add(t,g);g.gridwidth=1;g.gridy++;g.gridx=0;p.add(new JLabel("Thuật toán:"),g);g.gridx=1;p.add(algo,g);g.gridy++;g.gridx=0;p.add(new JLabel("Khóa:"),g);g.gridx=1;key.setText(CipherTongHop.sampleKey((String)algo.getSelectedItem()));p.add(key,g);g.gridy++;g.gridx=0;p.add(new JLabel("Plaintext:"),g);g.gridx=1;p.add(new JScrollPane(plain),g);g.gridy++;g.gridx=0;p.add(new JLabel("Ciphertext:"),g);g.gridx=1;p.add(new JScrollPane(cipher),g);JPanel b=new JPanel(new FlowLayout(FlowLayout.LEFT));JButton en=new JButton("Encrypt"),de=new JButton("Decrypt"),op=new JButton("Open File"),sv=new JButton("Save File"),sql=new JButton("Mở SQLite"),hist=new JButton("Xem lịch sử");for(JButton x:new JButton[]{en,de,op,sv,sql,hist})b.add(x);g.gridy++;g.gridx=0;g.gridwidth=2;p.add(b,g);algo.addActionListener(e->key.setText(CipherTongHop.sampleKey((String)algo.getSelectedItem())));en.addActionListener(e->run(true));de.addActionListener(e->run(false));op.addActionListener(e->{String x=FileTextIO.open(this,cipher);if(x!=null)status.setText("Đã mở "+x);});sv.addActionListener(e->{String x=FileTextIO.save(this,cipher,"ciphertext.txt");if(x!=null)status.setText("Đã lưu "+x);});sql.addActionListener(e->new frm_KetNoiSQL().setVisible(true));hist.addActionListener(e->new frm_LichSu().setVisible(true));add(p,BorderLayout.CENTER);status.setBorder(BorderFactory.createEmptyBorder(4,22,12,22));add(status,BorderLayout.SOUTH);}
 private void run(boolean enc){String a=(String)algo.getSelectedItem(),in=enc?plain.getText():cipher.getText();try{String out=enc?CipherTongHop.encrypt(a,in,key.getText()):CipherTongHop.decrypt(a,in,key.getText());if(enc)cipher.setText(out);else plain.setText(out);try{HistoryDao.insert(a,enc?"ENCRYPT":"DECRYPT",in,out);status.setText("Thành công; đã lưu lịch sử SQLite.");}catch(Exception sql){status.setText("Thao tác thành công; chưa ghi được SQLite: "+sql.getMessage());}}catch(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage(),"Lỗi dữ liệu",JOptionPane.ERROR_MESSAGE);}}
}
